            reject: [{ re: '^these (advantage|freedom|benefit)$', hint: 'One advantage: use "this".' },
              { re: '^this (advantages|benefits|gains)$', hint: 'After "this" use a singular noun.' },
              { re: 'for example', hint: 'This is not an example: it adds a second advantage.' }],
